CREATE TABLE IF NOT EXISTS intelligence_remediation_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), subject_type text NOT NULL, subject_id uuid NOT NULL, blocker_code text NOT NULL, title text NOT NULL, description text, required_evidence text, status text NOT NULL DEFAULT 'open', priority text NOT NULL DEFAULT 'high', assigned_to text, created_by text, completed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(subject_type,subject_id,blocker_code));